using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Preserve EF Core 8 id format ("Product|123") for existing 500K documents
        optionsBuilder.UseCosmos(o =>
        {
        });
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Breaking change #1: EF Core 9 renames "Discriminator" to "$type".
            // Existing documents use "Discriminator" — preserve it for backward compat.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change #2: EF Core 9 changes id format from "Product|123" to "123".
            // Existing documents use the old format — preserve it.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
        });

        // Breaking change #3: HasIndex() is no longer valid for Cosmos provider in EF Core 9.
        // Cosmos DB indexes are managed server-side via indexing policy, not EF.
        // REMOVED: modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

